fn run(terminal: &mut ratatui::DefaultTerminal, client: &mut Client) -> std::io::Result<()> {
    loop {
        let view = client.view();
        terminal.draw(|frame| draw(frame, &view))?;

        let CtEvent::Key(key) = event::read()? else {
            continue;
        };
        if key.kind != KeyEventKind::Press {
            continue;
        }
        match key.code {
            KeyCode::Char('q') | KeyCode::Esc => return Ok(()),
            KeyCode::Char('n') => client.dispatch(Action::New),
            KeyCode::Char('j') | KeyCode::Down => client.dispatch(Action::Next),
            KeyCode::Char('k') | KeyCode::Up => client.dispatch(Action::Prev),
            KeyCode::Char('d') => {
                if let Some(id) = client.app().selected().map(|doc| doc.id) {
                    client.dispatch(Action::Close(id));
                }
            }
            _ => {}
        }
    }
}


