fn main() {
    application().run(|cx: &mut App| {
        cx.bind_keys([
            KeyBinding::new("n", NewDoc, None),
            KeyBinding::new("j", NextDoc, None),
            KeyBinding::new("down", NextDoc, None),
            KeyBinding::new("k", PrevDoc, None),
            KeyBinding::new("up", PrevDoc, None),
            KeyBinding::new("d", CloseDoc, None),
            KeyBinding::new("q", Quit, None),
        ]);

        let bounds = Bounds::centered(None, size(px(720.), px(520.)), cx);
        cx.open_window(
            WindowOptions {
                window_bounds: Some(WindowBounds::Windowed(bounds)),
                ..Default::default()
            },
            |_, cx| cx.new(Root::new),
        )
        .expect("open window");
        cx.activate(true);
    });
}
